#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Personagem {
    string nome;
    int vida;
    int vidaMaxima;
};

// Soma qtd à vida, sem passar de vidaMaxima.
void curar(Personagem& p, int qtd) {
    p.vida += qtd;
    if (p.vida > p.vidaMaxima) {
        p.vida = p.vidaMaxima;
    }
}

// Se alvo for nullptr, devolve false. Senão, tira dano da vida (mínimo 0) e devolve true.
bool atacar(Personagem* alvo, int dano) {
    if (alvo == nullptr) {
        return false;
    }
    alvo->vida -= dano;
    if (alvo->vida < 0) {
        alvo->vida = 0;
    }
    return true;
}

// Ponteiro para o personagem vivo com menos vida (o primeiro, no empate), ou nullptr.
Personagem* maisFraco(vector<Personagem>& grupo) {
    Personagem* melhor = nullptr;
    for (Personagem& p : grupo) {
        if (p.vida > 0 && (melhor == nullptr || p.vida < melhor->vida)) {
            melhor = &p;
        }
    }
    return melhor;
}

int main() {
    vector<Personagem> grupo = {{"Ana", 30, 40}, {"Caio", 12, 35}, {"Duda", 0, 25}};

    Personagem* alvo = maisFraco(grupo);
    if (atacar(alvo, 5)) {
        cout << alvo->nome << " levou 5 de dano e ficou com " << alvo->vida << "." << endl;
    }

    curar(grupo[1], 100);
    cout << grupo[1].nome << " foi curado: " << grupo[1].vida << "/" << grupo[1].vidaMaxima << endl;

    cout << "Atacar ninguém: " << (atacar(nullptr, 5) ? "atacou" : "nada aconteceu") << endl;
    return 0;
}

