#include <iostream>
#include <string>
using namespace std;

int monstrosNaMemoria = 0;   // quantos Monstro existem agora

// Não mude esta classe.
class Monstro {
public:
    Monstro(string nome, int vida) : nome(nome), vida(vida) {
        monstrosNaMemoria++;
    }
    ~Monstro() {
        monstrosNaMemoria--;
