#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

// Não mude esta struct.
struct Item {
    string nome;
    int valor;
    Item(string nome, int valor) : nome(nome), valor(valor) {}
    ~Item() { cout << "(" << nome << " saiu da memória)" << endl; }
};

class Inventario {
public:
    void adicionar(string nome, int valor) {
        itens.push_back(make_unique<Item>(nome, valor));
    }

    int quantidade() const {
        return static_cast<int>(itens.size());
    }

    int valorTotal() const {
        int total = 0;
        for (const auto& item : itens) {
            total += item->valor;
        }
        return total;
    }

    Item* procurar(string nome) {
        int i = posicaoDe(nome);
        return i == -1 ? nullptr : itens[i].get();
    }

    bool descartar(string nome) {
        int i = posicaoDe(nome);
        if (i == -1) {
            return false;
        }
        itens.erase(itens.begin() + i);   // o unique_ptr apagado destrói o item
        return true;
    }

    bool entregar(string nome, Inventario& outro) {
        int i = posicaoDe(nome);
        if (i == -1) {
            return false;
        }
        outro.itens.push_back(move(itens[i]));   // o outro vira o dono
        itens.erase(itens.begin() + i);          // tira a casa vazia
        return true;
    }

private:
    vector<unique_ptr<Item>> itens;

    // Posição do primeiro item com esse nome, ou -1 se não houver.
    int posicaoDe(const string& nome) const {
        for (int i = 0; i < static_cast<int>(itens.size()); i++) {
            if (itens[i]->nome == nome) {
                return i;
            }
        }
        return -1;
    }
};

int main() {
    Inventario mochila;
    Inventario bau;
    mochila.adicionar("Espada", 50);
    mochila.adicionar("Escudo", 30);
    mochila.adicionar("Poção", 10);
    cout << "Itens na mochila: " << mochila.quantidade() << " | Valor: " << mochila.valorTotal() << endl;

    Item* espada = mochila.procurar("Espada");
    if (espada != nullptr) {
        espada->valor += 25;
        cout << "A espada foi afiada: agora vale " << espada->valor << endl;
    }

    mochila.descartar("Poção");
    mochila.entregar("Escudo", bau);
    cout << "Itens na mochila: " << mochila.quantidade() << " | Valor: " << mochila.valorTotal() << endl;
    cout << "Itens no baú: " << bau.quantidade() << " | Valor: " << bau.valorTotal() << endl;
    cout << "Fim da aventura." << endl;
    return 0;
}
